300	    /**
301	     * Return the Pet with the given name, or null if none found for this Owner.
302	     *
303	     * @param name to test
304	     * @return true if pet name is already in use
305	     */
306	    public Pet getPet(String name, boolean ignoreNew) {
307	        name = name.toLowerCase();
308	        for (Pet pet : getPetsInternal()) {
309	            if (!ignoreNew || !pet.isNew()) {
310	                String compName = pet.getName();
311	                compName = compName.toLowerCase();
312	                if (compName.equals(name)) {
313	                    return pet;
314	                }
315	            }
316	        }
317	        return null;
318	    }
