1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;
7	
8	/**
9	 * Flags a create-owner request as approaching its city's capacity limit. Runs before
10	 * {@link SaveOwner}, so {@link OwnerRepository#findAll()} returns only the owners that predate this
11	 * create. It counts those already registered in this owner's city (compared case-insensitively and
12	 * trimmed, mirroring {@link EnsureCityCapacity}) and sets {@code capacityWarning} true when that
13	 * count is between {@link #WARNING_THRESHOLD} and one below the hard
14	 * {@link CityAtCapacityException#CAPACITY} limit (40-49); otherwise false. A city already at
15	 * capacity is rejected earlier by {@link EnsureCityCapacity}, so this step never sees 50 or more.
16	 */
17	public class FlagCapacityWarning {
18	
19	    /** A city already holding at least this many owners warns the next create. */
20	    public static final int WARNING_THRESHOLD = 40;
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String city = normalize(owner.getCity());
24	        int count = 0;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (city.equals(normalize(existing.getCity()))) {
27	                count++;
28	            }
29	        }
30	        owner.setCapacityWarning(count >= WARNING_THRESHOLD && count < CityAtCapacityException.CAPACITY);
31	    }
32	
33	    private static String normalize(String value) {
34	        return value == null ? "" : value.trim().toLowerCase();
35	    }
36	}
