1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Set;
4	import java.util.regex.Pattern;
5	
6	import org.springframework.samples.petclinic.rest.escalation.DisposableEmailException;
7	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
8	
9	/**
10	 * Normalizes the optional owner {@code email}. Email is absent when null or blank; when present it must
11	 * be a syntactically valid address whose domain is not on the disposable-domain blocklist, and is
12	 * stored/returned lower-cased.
13	 */
14	final class OwnerEmail {
15	
16	    /**
17	     * A pragmatic syntactic check: a non-empty local part, a single {@code @}, and a domain carrying at
18	     * least one dot, none of the three parts containing whitespace or an {@code @}.
19	     */
20	    private static final Pattern SYNTAX = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
21	
22	    /**
23	     * Disposable email domains that are rejected: an address in one of these is a throwaway inbox, so
24	     * an owner supplying one is a 400.
25	     */
26	    private static final Set<String> BLOCKED_DOMAINS = Set.of(
27	            "mailinator.com", "tempmail.com", "guerrillamail.com");
28	
29	    private OwnerEmail() {
30	    }
31	
32	    /**
33	     * @return the trimmed, lower-cased email, or {@code null} when it is absent (null or blank).
34	     * @throws InvalidEmailException when present but not syntactically valid.
35	     * @throws DisposableEmailException when present and its domain is on the disposable-domain blocklist.
36	     */
37	    static String normalize(String email) throws InvalidEmailException, DisposableEmailException {
38	        if (email == null || email.isBlank()) {
39	            return null;
40	        }
41	        String trimmed = email.trim();
42	        if (!SYNTAX.matcher(trimmed).matches()) {
43	            throw new InvalidEmailException(email);
44	        }
45	        String normalized = trimmed.toLowerCase();
46	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
47	        if (BLOCKED_DOMAINS.contains(domain)) {
48	            throw new DisposableEmailException(email);
49	        }
50	        return normalized;
51	    }
52	}
