3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
8	
9	/**
10	 * The single source of truth for an owner's derived {@code identityKey} and its parts. All duplicate
11	 * detection is now expressed through this one key:
12	 *
13	 * <pre>identityKey = SHA-256 hex over (normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName))</pre>
14	 *
15	 * <p>Two owners are duplicates only when their <em>whole</em> identityKey is equal. Because the
16	 * telephone is part of the key, two owners with the same last name (and postcode) but different
17	 * telephones have different identityKeys and are both allowed; only an exact full-key match is a
18	 * duplicate. Postcode is <em>not</em> part of the key, so the household id derived from (lastName,
19	 * postcode) no longer feeds duplicate detection — it survives only as descriptive metadata (see
20	 * {@link #deriveHouseholdId}).
21	 */
22	public final class OwnerIdentity {
23	
24	    private OwnerIdentity() {
25	    }
26	
27	    /**
28	     * The identityKey for a create request or an existing owner — the one derivation the duplicate
29	     * check applies to both sides of a comparison, so a request and an existing owner are keyed
30	     * identically. It is the SHA-256 hex (lower-case, 64 characters) of
31	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}: telephone is
32	     * canonicalized to E.164 and email is lower-cased so differing formats or case do not hide a match,
33	     * and the last name folds through Soundex so it matches phonetically.
34	     */
35	    public static String key(String telephone, String email, String lastName) {
36	        String input = canonicalTelephone(telephone) + '|' + normalizedEmail(email) + '|'
37	                + soundex(lastName);
38	        return sha256HexLower(input);
39	    }
40	
41	    /**
42	     * The E.164 form used for comparison. A value that is already E.164 is returned unchanged; a value
43	     * that predates E.164 storage is normalized on the fly, falling back to its bare digits if it
44	     * cannot form valid E.164.
45	     */
46	    public static String canonicalTelephone(String value) {
47	        try {
48	            return OwnerTelephone.toE164(value);
49	        }
50	        catch (InvalidTelephoneException ex) {
51	            return value == null ? "" : value.replaceAll("\\D", "");
52	        }
53	    }
54	
55	    /** The email lower-cased and trimmed, or the empty string when null or blank. */
56	    public static String normalizedEmail(String value) {
57	        if (value == null || value.isBlank()) {
58	            return "";
59	        }
60	        return value.trim().toLowerCase();
61	    }
62	
63	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
64	    public static String normalizeName(String value) {
65	        if (value == null) {
66	            return "";
67	        }
68	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
69	    }
70	
71	    /**
72	     * The deterministic household id: the first 12 hex characters of SHA-256 over
73	     * {@code normalizedLastName + '|' + postcode}. Owners with the same normalized lastName and
74	     * postcode therefore resolve to the same value automatically, so the household is keyed on
75	     * (lastName, postcode). A null postcode is treated as the empty string.
76	     */
77	    public static String deriveHouseholdId(String normalizedLastName, String postcode) {
78	        return sha256Hex(normalizedLastName + '|' + (postcode == null ? "" : postcode), 12);
79	    }
80	
81	    /**
82	     * The household id for a raw (un-normalized) {@code lastName} and {@code postcode} — normalizes the
83	     * lastName and defers to {@link #deriveHouseholdId}. This is the one derivation every household
84	     * check shares, so two owners resolve to the same household exactly when this returns the same
85	     * value.
86	     */
87	    public static String householdIdOf(String lastName, String postcode) {
88	        return deriveHouseholdId(normalizeName(lastName), postcode);
89	    }
90	
91	    /**
92	     * HASH8: the first 8 upper-case hex characters of SHA-256 over {@code normalizedTelephone +
93	     * lastName}, where the telephone is canonicalized to E.164. This is the hashed component of the
94	     * owner's {@code memberId} ({@code <REGION><FY><HASH8><CHK>}).
95	     */
96	    public static String customerHash(String telephone, String lastName) {
97	        return sha256Hex(canonicalTelephone(telephone) + (lastName == null ? "" : lastName), 8);
98	    }
99	
100	    /**
101	     * The Luhn check digit (0-9) over the decimal digits contained in {@code source}; any non-digit
102	     * character is skipped. This is the check-digit primitive the owner's {@code memberId} carries as
103	     * its CHK segment — computed over {@code <REGION><FY><HASH8>}.
104	     */
105	    public static int luhnCheckDigit(String source) {
106	        int sum = 0;
107	        boolean dbl = true;
108	        for (int i = source.length() - 1; i >= 0; i--) {
109	            char c = source.charAt(i);
110	            if (c < '0' || c > '9') {
111	                continue;
112	            }
113	            int d = c - '0';
114	            if (dbl) {
115	                d *= 2;
116	                if (d > 9) {
117	                    d -= 9;
118	                }
119	            }
120	            sum += d;
121	            dbl = !dbl;
122	        }
123	        return (10 - (sum % 10)) % 10;
124	    }
125	
126	    /**
127	     * The full SHA-256 over the UTF-8 bytes of {@code input} as 64 lower-case hex characters — the
128	     * encoding of the owner's {@code identityKey}.
129	     */
130	    static String sha256HexLower(String input) {
131	        StringBuilder sb = new StringBuilder(64);
132	        for (byte b : sha256(input)) {
133	            sb.append(String.format("%02x", b));
134	        }
135	        return sb.toString();
136	    }
137	
138	    /**
139	     * The American Soundex code of {@code name}: the first letter followed by three digits, folding
140	     * consonants to their phonetic class so names that sound alike share a code (e.g. {@code Robert}
141	     * and {@code Rupert} both give {@code R163}). Non-letters are dropped first; a null or letter-less
142	     * name yields the empty string. Adjacent letters of the same class — and same-class letters
143	     * separated by {@code H} or {@code W} — are coded once; a vowel between them resets the run so both
